  "target_detail": "한센인피해사건진상규명위원회에서 피해자로 결정한 사람을 지원합니다.&#13;「한센인피해사건의 진상규명 및 피해자 지원 등에 관한 법률」에 따라 위원회의 심의·의결로 결정된 피해자(생존자 본인에 한함)를 &#13;(위로지원금) 소득에 관계없이 한센인 피해자로 결정된 모든 한센인&#13;(의료지원금) 위원회에서 의료지원금 지급을 결정한 자&#13;",
