  "target_detail": "소아 암환자 의료비 지원 대상자는 다음과 같습니다.&#13;(대상자) 건강보험(소득재산조사 기준 충족) 의료급여(당연선정), 만18세 미만 연속&#13;(지원암종) 전체암종&#13;(지원금액) 백혈병 3,000만원, 기타 2,000만원(조혈모세포이식 시 3,000만원)&#13;해당 사업은 관할 보건소를 통해 신청하여 이용가능합니다.&#13;성인 암환자 의료비 지원 내용은 다음과 같습니다.&#13;(대상자) 의료급여수급권자 당연선정 및 연속 최대 3년 지원, 건강보험가입자 차상위 본인 부담 경감 대상자 * 단, 건강보험가입자(50%…",
